import EventEmitter from 'phaser3-rex-plugins/plugins/utils/eventemitter/EventEmitter';

/** Также тут можно использовать
 *  import EventEmitter from 'eventemitter3';
 * **/

export enum SolitaireAction {
    MOVE_TABLEAU_TO_TABLEAU = "MOVE_TABLEAU_TO_TABLEAU",
    MOVE_STOCK_TO_TABLEAU = "MOVE_STOCK_TO_TABLEAU",
    MOVE_TO_FOUNDATION = "MOVE_TO_FOUNDATION",
    UNDO = "UNDO",
    STOCK_RECYCLE = "STOCK_RECYCLE",
    GAME_WON = "GAME_WON",
}

export interface IKlondikeEvents {
    solitaireAction: SolitaireAction;
}

export class KlondikeEventsEmitter {
    private emitter = new EventEmitter<IKlondikeEvents>();

    unSubscribeAll() {
        this.emitter.removeAllListeners();
    }

    on<T extends keyof IKlondikeEvents>(
        event: T,
        callback: (data: IKlondikeEvents[T]) => void,
    ): () => void {
        this.emitter.on(event, callback as (...args: unknown[]) => void);
        return () => this.off(event, callback);
    }

    once<T extends keyof IKlondikeEvents>(
        event: T,
        callback: (data: IKlondikeEvents[T]) => void,
        timeout?: number,
    ): () => void {
        this.emitter.once(event, callback);

        let timeoutId: number | undefined;

        if (timeout) {
            timeoutId = window.setTimeout(() => {
                this.off(event, callback);
                callback(undefined as IKlondikeEvents[T]);
            }, timeout);
        }

        return () => {
            this.off(event, callback);
            if (timeoutId) {
                clearTimeout(timeoutId);
            }
        };
    }

    async wait<T extends keyof IKlondikeEvents>(event: T): Promise<IKlondikeEvents[T]> {
        return new Promise((resolve) => {
            this.emitter.once(event, resolve as (...args: unknown[]) => void);
        });
    }

    off<T extends keyof IKlondikeEvents>(event: T, callback: (data: IKlondikeEvents[T]) => void) {
        this.emitter.off(event, callback as (...args: unknown[]) => void);
    }

    emit<T extends keyof IKlondikeEvents>(event: T, data?: IKlondikeEvents[T]) {
        this.emitter.emit(event, ...(data !== undefined ? [data] : []));
    }
}
