import { services } from "../../../serviceProvider";
import { SoundManager } from "../../../ui";
import { ASSETS, BackgroundAssetBuilder, getCurrentLocale } from "../../../assets";
import { Align, cssColorToInt } from "@kvisaz/phaser-sugar";
import {
  centeredCardLayoutStrategy,
  klondikeGraveLayoutStrategy,
  showValueCardFromTopLayoutStrategy,
} from "../../../common/games/cards-layout";
import { addBackButton } from "../utils";
import { resetSearchParam } from "../../../common";
import { Scenes } from "../../routes";
import { KlondikeView } from "../../GameScene/KlondikeView";

export class KlondikedViewTestScene extends Phaser.Scene {
  preload() {}

  create() {
    const scene = this;
    const { soundMusicSettings } = services;
    const soundManager = new SoundManager({ scene, soundMusicSettings });
    new BackgroundAssetBuilder(scene).sceneBg();
    const locale = getCurrentLocale();

    const simpleTextBuilder = (str: string = "", bounds: { width?: number; height?: number } = {}) => {
      const text = new Phaser.GameObjects.Text(scene, 0, 0, str, {
        fontFamily: ASSETS.font.fonts.RobotoBold.fontFamily,
        color: "#dedede",
        fontSize: `${24}px`,
        align: "center",
      });
      const rectangle = new Phaser.GameObjects.Rectangle(
        scene,
        0,
        0,
        bounds.width ?? 150,
        bounds.height ?? 200,
        cssColorToInt("#7a7851"),
        0.5,
      );
      rectangle.setStrokeStyle(2, cssColorToInt("#7a7851"));

      new Align(rectangle).center(text);
      const container = new Phaser.GameObjects.Container(scene, 0, 0, [rectangle, text]);

      scene.add.existing(container);
      const { width, height } = container.getBounds();
      container.setSize(width, height);
      return container;
    };

    /** backCover button **/
    addBackButton({
      scene: this,
      onClick: () => {
        resetSearchParam("test");
        scene.scene.start(Scenes.TestScene);
      },
    });

    /** fieldMargins **/
    const fieldMargin = { left: 16, right: 16, top: 58, bottom: 16 };
    const fieldBounds = new Phaser.GameObjects.Rectangle(
      scene,
      fieldMargin.left,
      fieldMargin.top,
      scene.sys.canvas.width - fieldMargin.left - fieldMargin.right,
      scene.sys.canvas.height - fieldMargin.top - fieldMargin.bottom,
      cssColorToInt("#dedede"),
      0,
    ).setOrigin(0, 0);
    scene.add.existing(fieldBounds);

    const zoneBounds = { width: 150, height: 200 };

    /** klondikeView **/
    const klondikeView = new KlondikeView({
      scene,
      locale,
      fieldBounds,
      builders: {
        deckZone: () => simpleTextBuilder("deck", zoneBounds),
        graveZone: () => simpleTextBuilder("grave", zoneBounds),
        baseBuilder: () => simpleTextBuilder("base", zoneBounds),
        pileBuilder: () => simpleTextBuilder("pile", { ...zoneBounds, height: zoneBounds.height * 2.5 }),
      },
      cardLayout: {
        deck: centeredCardLayoutStrategy,
        grave: klondikeGraveLayoutStrategy,
        base: centeredCardLayoutStrategy,
        pile: (cards, inputZone) => showValueCardFromTopLayoutStrategy(cards, inputZone, { offsetY: 32 }),
      },
    });

    klondikeView.events.on("solitaireAction", (action) => {
      console.log("🎮 Klondike Event:", action);
    });
  }
}
