import { playOrResumeMusicWithLoading } from "../../common";

const soundNames = {
  click: "click",
  coinFlip: "coinFlip",
  buttonHover: "buttonHover",
  cardFlip: "cardFlip",
  cardMultipleFlip: "cardMultipleFlip",
  catPurr: "catPurr",
  winEffect: "winEffect",
};

interface IAssetSound {
  url: string;
  volume: number;
}

/** todo delete **/
const musicTracks = {
  tavern: "medieval-citytavern-ambient.mp3",
  rpg: "rpg-medieval-animated-music.mp3",
};

const musicSound: IAssetSound = {
  url: `./assets/music/${musicTracks.rpg}`,
  volume: 0.15,
};

export type AssetSound = keyof typeof soundNames;

export const AssetSounds = {
  /** просто указывает на старт загрузки **/
  load(scene: Phaser.Scene): void {
    scene.load.audio(soundNames.click, "./assets/sounds/click.mp3");
    scene.load.audio(soundNames.coinFlip, "./assets/sounds/coin.flip.mp3");
    scene.load.audio(soundNames.buttonHover, "./assets/sounds/card.flip.single.hover.sfx_03.mp3");
    scene.load.audio(soundNames.cardFlip, "./assets/sounds/card.flip.single.sfx_02.mp3");
    scene.load.audio(soundNames.cardMultipleFlip, "./assets/sounds/card.flip.multiple.sfx_01.mp3");
    scene.load.audio(soundNames.catPurr, "./assets/sounds/cat-purr-33835.mp3");
    scene.load.audio(soundNames.winEffect, "./assets/sounds/orchestral-win-331233_trimmed.mp3");
  },

  effect: {
    click: (scene: Phaser.Scene) => play(scene, "click", 1),
    coinFlip: (scene: Phaser.Scene) => play(scene, "coinFlip", 1),
    mouseHover: (scene: Phaser.Scene) => play(scene, "buttonHover", 1),
    cardFlip: (scene: Phaser.Scene) => play(scene, "cardFlip", 1),
    cardMultipleFlip: (scene: Phaser.Scene) => play(scene, "cardMultipleFlip", 1),
    catPurr: (scene: Phaser.Scene) => play(scene, "catPurr", 1),
    winEffect: (scene: Phaser.Scene) => play(scene, "winEffect", 0.5),
  },
  music: {
    playResumeLoad: (scene: Phaser.Scene) => {
      playOrResumeMusicWithLoading({
        scene,
        key: musicSound.url,
        url: musicSound.url,
        options: {
          volume: musicSound.volume,
        },
      });
    },
    pause: (scene: Phaser.Scene) => {
      scene.sound.get(musicSound.url)?.pause();
    },
    stop: (scene: Phaser.Scene) => {
      scene.sound.get(musicSound.url)?.stop();
    },
  },
};

function play(scene: Phaser.Scene, soundName: AssetSound, volume = 1): void {
  scene.sound.play(soundName, {
    volume,
  });
}
