type InputTracker =
  | Phaser.GameObjects.Text
  | Phaser.GameObjects.Image
  | Phaser.GameObjects.NineSlice
  | Phaser.GameObjects.Sprite;

type GameObject =
  | Phaser.GameObjects.Text
  | Phaser.GameObjects.Image
  | Phaser.GameObjects.NineSlice
  | Phaser.GameObjects.Sprite
  | Phaser.GameObjects.Container;

interface IProps {
  gameObject: GameObject;
  /** для контейнеров обязательно указывать inputTracker внутри контейнера **/
  inputTracker: InputTracker;
  onClick: () => void;
  onOver?: () => void;
  onOut?: () => void;
  options?: {
    once?: boolean;
    clickMode?: "down" | "up";
    overMoveY?: number;
  };
}

const defaultOptions = {
  clickMode: "up",
  overMoveY: 6,
  once: true
} as const;

export function gameObjectButton({
                                   gameObject,
                                   inputTracker,
                                   onClick,
                                   onOver,
                                   onOut,
                                   options = {}
                                 }: IProps): GameObject {
  options = {
    ...defaultOptions,
    ...options
  };

  let isClickDisabled = false;

  const buttonClick = () => {
    if (isClickDisabled) return;
    if (options.once) {
      isClickDisabled = true;
    }
    onClick();
  };

  let isOverEffect = false;


  const pressEffectState = {
    isChanged: false,
    position: { x: gameObject.x, y: gameObject.y }
  }
  const addPressEffect = () => {
    if(pressEffectState.isChanged) return;
    pressEffectState.isChanged = true;

    pressEffectState.position.x = gameObject.x;
    pressEffectState.position.y = gameObject.y;

    const offsetY =  options?.overMoveY ?? 0;
    gameObject.y += offsetY
  };

  const clearPressEffect = () => {
    if(!pressEffectState.isChanged) return;
    pressEffectState.isChanged = false;

    gameObject.x = pressEffectState.position.x;
    gameObject.y = pressEffectState.position.y;
  };

  const addOverEffect = () => {
    if (isOverEffect) return;
    isOverEffect = true;
    gameObject.postFX.addGlow();
  };

  const clearOverEffect = () => {
    if (!isOverEffect) return;
    isOverEffect = false;
    gameObject.postFX?.clear();
  };

  inputTracker.setInteractive({
    useHandCursor: true
  });

  inputTracker.on(Phaser.Input.Events.GAMEOBJECT_POINTER_OVER, () => {
    if (isClickDisabled) return;
    onOver?.();
    addOverEffect();
  });

  inputTracker.on(Phaser.Input.Events.GAMEOBJECT_POINTER_OUT, () => {
    if (isClickDisabled) return;
    onOut?.();
    clearOverEffect();
  });

  inputTracker.on(Phaser.Input.Events.GAMEOBJECT_POINTER_DOWN, () => {
    if (isClickDisabled) return;
    clearOverEffect();
    addPressEffect();

    if (options.clickMode === "down") {
      buttonClick();
    }
  });

  inputTracker.on(Phaser.Input.Events.GAMEOBJECT_POINTER_UP, () => {
    if (isClickDisabled) return;
    addOverEffect();
    clearPressEffect();
    if (options.clickMode === "up") buttonClick();
  });

  const scene = gameObject.scene;
  scene.input.on(Phaser.Input.Events.GAME_OUT, () => {
    clearPressEffect();
    clearOverEffect();
  })

  return gameObject;
}
