import { Align, cssColorToInt } from "@kvisaz/phaser-sugar";
import { uiTextButton } from "./buttons";
import { getCanvasSize } from "../common";

export interface IButton {
  label: string;
  onClick: () => void;
  type?: "primary" | "accent";
}

/** фон, контент, универсальные блоки **/
export type DialogLayer =
  | Phaser.GameObjects.Container
  | Phaser.GameObjects.Image
  | Phaser.GameObjects.Rectangle
  | Phaser.GameObjects.NineSlice
  | Phaser.GameObjects.Text;

interface IProps {
  scene: Phaser.Scene;
  bgBuilder: () => DialogLayer;
  contentFrameBuilder: () => DialogLayer;
  contentBuilder: (contentFrame: DialogLayer) => DialogLayer;
  overlayAlpha?: number;
  buttons: IButton[];
}

/**
 * Общий диалог для игры
 * зависит от текущих ассетов
 * (поэтому не годится для мгновенного переноса куда-то в другую игру,
 * надо менять ассеты)
 * и кнопки uiTextButton, которая тоже зависит от ассетов
 **/
export class UiCommonDialog extends Phaser.GameObjects.Container {
  protected overLay: Phaser.GameObjects.Rectangle;

  constructor({ scene, buttons, bgBuilder, contentBuilder, contentFrameBuilder, overlayAlpha = 0.46 }: IProps) {
    super(scene);
    const align = new Align();

    const canvasSize = getCanvasSize(scene);

    const closeDialog = (onClose: () => void) => {
      scene.tweens.add({
        targets: this,
        props: {
          y: canvasSize.height + 100,
        },
        ease: Phaser.Math.Easing.Bounce.InOut,
        duration: 200,
        delay: 0,
        onComplete: () => {
          this.overLay.destroy();
          this.destroy();
          onClose();
        },
      });
    };

    /** frames, bg **/
    const baseFrame = bgBuilder();
    const contentFrame = contentFrameBuilder();
    align.anchor(baseFrame).centerX(contentFrame).topIn(contentFrame, 23);
    this.add([baseFrame, contentFrame]);

    /** content - contentBuilder  **/
    const content = contentBuilder(contentFrame);
    align.anchor(contentFrame).center(content);
    this.add(content);

    /** buttons **/
    const buttonsContainer = new Phaser.GameObjects.Container(scene);
    let prevX = 0;
    const padding = 10;
    const buttonViews = buttons.map((button) => {
      const buttonView = uiTextButton({
        text: button.label,
        onClick: () => {
          closeDialog(() => {
            button.onClick();
          });
        },
        type: button.type,
        width: 320,
        height: 80,
        fontSizePx: 55,
        scene: scene,
      });
      const bounds = buttonView.getBounds();
      align.setPosition(buttonView, prevX, 0);
      prevX += bounds.width + padding;
      return buttonView;
    });
    buttonsContainer.add(buttonViews);

    align.anchor(contentFrame).center(buttonsContainer).bottomTo(buttonsContainer, 10);
    this.add([buttonsContainer]);

    /** overlay add **/
    this.overLay = new Phaser.GameObjects.Rectangle(
      scene,
      0,
      0,
      canvasSize.width,
      canvasSize.height,
      cssColorToInt("#000000"),
      overlayAlpha,
    ).setInteractive();
    align.anchorSceneScreen(scene).center(this.overLay);
    scene.add.existing(this.overLay);

    /** show! **/
    align.anchorSceneScreen(scene).center(this);
    const targetY = this.y;
    align.anchorSceneScreen(scene).bottomTo(this);
    scene.add.existing(this);

    scene.tweens.add({
      targets: this,
      props: {
        y: targetY,
      },
      ease: Phaser.Math.Easing.Bounce.InOut,
      duration: 200,
      delay: 0,
    });
  }

  destroy(fromScene?: boolean) {
    super.destroy(fromScene);
    this.overLay.destroy();
  }
}
