import { atlases } from "./atlases";

type AtlasKey = keyof typeof atlases;

const atlasesNames = Object.keys(atlases) as AtlasKey[];

export const AssetImages = {
  /** просто указывает на старт загрузки **/
  load(scene: Phaser.Scene): void {
    atlasesNames.forEach((atlasName) => {
      const atlas = atlases[atlasName];
      scene.load.atlas(atlas.textureName, atlas.textureName, atlas.jsonName);
    });
  },

  atlases,
};
