import { IStorage } from "./contracts";
import { ISoundMusicOptions } from "./interfaces";

interface IProps {
  cloudStorage: IStorage;
}

const KEY = "soundSettings";

const defaultOptions: ISoundMusicOptions = {
  isMusicOn: true,
  isSoundOn: true,
};

/** Настройки звуков
 *  Создавайте в момент использования в конкретной сцене!
 *  проверяйте в момент запуска звуков
 *  **/
export class SoundMusicSettings {
  private options: ISoundMusicOptions;

  constructor(private props: IProps) {
    this.options = {
      ...defaultOptions,
      ...this.cloudOptions,
    };
  }

  /**
   * вызывай всегда перед проверкой
   *  **/
  load() {
    this.options = {
      ...this.options,
      ...this.cloudOptions,
    };
  }

  save() {
    this.uploadOptions();
  }

  isMusicOn() {
    return this.options.isMusicOn;
  }

  isSoundOn() {
    return this.options.isSoundOn;
  }

  setMusicOn(isMusicOn: boolean) {
    this.options.isMusicOn = isMusicOn;
  }

  /** возвращает новое значение **/
  switchMusicPlay() {
    this.setMusicOn(!this.options.isMusicOn);
    return this.options.isMusicOn;
  }

  setSoundOn(isSoundOn: boolean) {
    this.options.isSoundOn = isSoundOn;
  }

  switchSoundPlay() {
    this.setSoundOn(!this.options.isSoundOn);
    return this.options.isSoundOn;
  }

  /** fast and lightweight **/
  private get cloudOptions(): ISoundMusicOptions {
    const cloudData = this.props.cloudStorage.get<ISoundMusicOptions>({ key: KEY });
    return typeof cloudData === "object" ? { ...this.options, ...cloudData } : { ...this.options };
  }

  private uploadOptions() {
    this.props.cloudStorage.set({
      key: KEY,
      data: this.options,
    });
  }
}
