import { Scenes } from "../routes";
import { GameOverView } from "./GameOverView";
import { IGameOverSceneData } from "../interfaces";
import { services } from "../../serviceProvider";
import { SoundManager } from "../../ui";
import { globalEvents } from "../../globalEvents";

export class GameOverScene extends Phaser.Scene {
  constructor() {
    super(Scenes.GameOver);
  }

  preload() {}

  create(gameOverData: IGameOverSceneData) {
    const { soundMusicSettings } = services;
    new SoundManager({ scene: this, soundMusicSettings });
    globalEvents.emit("gameOverSceneStart");

    new GameOverView({ scene: this, gameOverData });
  }
}
