import packageInfo from "../package.json";
import { phaserGameConfig } from "./config";
import { gameScenes } from "./scenes";
import { getLocalizedText } from "./assets";

console.log(`${packageInfo.name} ${packageInfo.version} starting...`);
console.log(`${packageInfo.description}`);
console.log("...................");

new Phaser.Game({
  ...phaserGameConfig,
  scene: [...gameScenes],
});

/* ---------------------------------------------------------
 *  Отключаем контекстное меню браузера
 * --------------------------------------------------------- */
document.body.addEventListener("contextmenu", (e) => e.preventDefault());

/* ---------------------------------------------------------
 *  Включаем локализованный title
 * --------------------------------------------------------- */
const titleText = getLocalizedText("start.logo.title");
const subTitleText = getLocalizedText("start.logo.subtitle");
document.title = `${titleText} - ${subTitleText}`;
