import { loadAssets } from "@kvisaz/phaser-sugar";
import { AssetImages } from "./AssetImages";
import { MineSweeperFonts } from "./fonts";
import { AssetSounds } from "./sound";

const defaultProgressCallback = (progress: number) => {
  console.log("progress", progress);
};

/** пронизывающий все реализации синглтон с ассетами **/
export const ASSETS = {
  /** просто вставь в предварительный загрузчик **/
  bootPreload(scene: Phaser.Scene) {
    // надо ли добавить что-то еще
    AssetSounds.load(scene);

    // todo шрифты последнего дизайна
    MineSweeperFonts.load(scene);

    // чистить
    AssetImages.load(scene);
  },

  /** загружает с прогрессом все ассеты игры **/
  async load(scene: Phaser.Scene, progressCallback = defaultProgressCallback): Promise<void> {
    await loadAssets(
      scene,
      (scene) => {
        ASSETS.bootPreload(scene);
      },
      progressCallback,
    );
  },

  images: AssetImages,
  font: MineSweeperFonts,
  sounds: AssetSounds,
};
