import { Align, cssColorToInt } from "@kvisaz/phaser-sugar";
import { ASSETS } from "../assets";
import { uiTextButton } from "./buttons";
import { getCanvasSize } from "../common";

interface IButton {
  label: string;
  onClick: () => void;
  type?: "primary" | "accent";
}

interface IProps {
  scene: Phaser.Scene;
  icon?: Phaser.GameObjects.Image;
  iconOffset?: { x: number; y: number };
  overlayAlpha?: number;
  title: string;
  titleTextStyle?: Phaser.Types.GameObjects.Text.TextStyle;
  text: string;
  buttons: IButton[];
  frameBuilder: (w: number, h: number) => Phaser.GameObjects.Image | Phaser.GameObjects.NineSlice;
  contentFrameBuilder: (w: number, h: number) => Phaser.GameObjects.Image | Phaser.GameObjects.NineSlice;
}

const defaultOffset = { x: 0, y: 0 };

/**
 * Общий диалог для игры
 * зависит от текущих ассетов
 * (поэтому не годится для мгновенного переноса куда-то в другую игру,
 * надо менять ассеты)
 * и кнопки uiTextButton, которая тоже зависит от ассетов
 **/
export class UiDialog extends Phaser.GameObjects.Container {
  private overLay: Phaser.GameObjects.Rectangle;

  constructor({
    scene,
    icon,
    title,
    titleTextStyle,
    text,
    buttons,
    iconOffset = defaultOffset,
    overlayAlpha = 0.46,
    frameBuilder,
    contentFrameBuilder,
  }: IProps) {
    super(scene);
    const align = new Align();

    const canvasSize = getCanvasSize(scene);

    const closeDialog = (onClose: () => void) => {
      scene.tweens.add({
        targets: this,
        props: {
          y: canvasSize.height + 100,
        },
        ease: Phaser.Math.Easing.Bounce.InOut,
        duration: 200,
        delay: 0,
        onComplete: () => {
          this.overLay.destroy();
          this.destroy();
          onClose();
        },
      });
    };

    /** frames, bg **/
    const baseFrame = frameBuilder(770, 464);
    const contentFrame = contentFrameBuilder(728, 332);
    align.anchor(baseFrame).centerX(contentFrame).topIn(contentFrame, 23);
    this.add([baseFrame, contentFrame]);

    /** columns **/
    const contentBounds = contentFrame.getBounds();
    const column1Width = contentBounds.width * 0.4;
    const column1Height = contentBounds.height;
    const column2Width = contentBounds.width - column1Width;
    const column2Height = contentBounds.height;

    const textMaxWidth = Math.floor(column2Width * 0.9);

    const contentCol1 = new Phaser.GameObjects.Rectangle(
      scene,
      0,
      0,
      column1Width,
      column1Height,
      cssColorToInt("#d2ff8e"),
      0,
    );
    const contentCol2 = new Phaser.GameObjects.Rectangle(
      scene,
      0,
      0,
      column2Width,
      column2Height,
      cssColorToInt("#551054"),
      0,
    );
    align.anchor(contentFrame).leftIn(contentCol1).topIn(contentCol1);
    align.anchor(contentCol1).rightTo(contentCol2).topIn(contentCol2);
    this.add([contentCol1, contentCol2]);

    /** icon **/
    if (icon) {
      align.anchor(contentCol1).centerX(icon, iconOffset?.x).centerY(icon, iconOffset?.y);
      this.add([icon]);
    }

    /** text **/
    const textContainer = new Phaser.GameObjects.Container(scene);
    const titleText = new Phaser.GameObjects.Text(scene, 0, 0, title, {
      fontFamily: ASSETS.font.fonts.RobotoBold.fontFamily,
      fontSize: "56px",
      color: titleTextStyle?.color ?? "#23394c",
      align: "center",
      wordWrap: {
        width: textMaxWidth,
      },
    });

    const textText = new Phaser.GameObjects.Text(scene, 0, 0, text, {
      fontFamily: ASSETS.font.fonts.RobotoSemiBold.fontFamily,
      fontSize: "32px",
      color: "#23394c",
      align: "center",
      wordWrap: {
        width: textMaxWidth,
      },
    });
    align.anchor(titleText).centerX(textText).bottomTo(textText, 20);
    textContainer.add([titleText, textText]);

    align.anchor(contentCol2).center(textContainer);
    this.add([textContainer]);

    /** buttons **/
    const buttonsContainer = new Phaser.GameObjects.Container(scene);
    let prevX = 0;
    const padding = 10;
    const buttonViews = buttons.map((button) => {
      const buttonView = uiTextButton({
        text: button.label,
        onClick: () => {
          closeDialog(() => {
            button.onClick();
          });
        },
        type: button.type,
        width: 320,
        height: 80,
        fontSizePx: 55,
        scene: scene,
      });
      const bounds = buttonView.getBounds();
      align.setPosition(buttonView, prevX, 0);
      prevX += bounds.width + padding;
      return buttonView;
    });
    buttonsContainer.add(buttonViews);

    align.anchor(contentFrame).center(buttonsContainer).bottomTo(buttonsContainer, 10);
    this.add([buttonsContainer]);

    /** overlay add **/
    this.overLay = new Phaser.GameObjects.Rectangle(
      scene,
      0,
      0,
      canvasSize.width,
      canvasSize.height,
      cssColorToInt("#000000"),
      overlayAlpha,
    ).setInteractive();
    align.anchorSceneScreen(scene).center(this.overLay);
    scene.add.existing(this.overLay);

    /** show! **/
    align.anchorSceneScreen(scene).center(this);
    const targetY = this.y;
    align.anchorSceneScreen(scene).bottomTo(this);
    scene.add.existing(this);

    scene.tweens.add({
      targets: this,
      props: {
        y: targetY,
      },
      ease: Phaser.Math.Easing.Bounce.InOut,
      duration: 200,
      delay: 0,
    });
  }

  destroy(fromScene?: boolean) {
    super.destroy(fromScene);
    this.overLay.destroy();
  }
}
