interface IDestroyerProxyProps {
  scene: Phaser.Scene;
  destroy: ()=>void;
}

/**
 * @deprecated по какой-то причине это не работает, не вызывается props.destroy()
 * estroyer proxy - если нужно быстро
 * упаковать разрушение в какой-то классический контейнер или группу
 * используется зона, потому что группы нельзя паковтаь в группы
 **/
export class DestroyerProxy extends Phaser.GameObjects.Zone {
  constructor(private props: IDestroyerProxyProps) {
    super(props.scene, 0, 0);
  }

  destroy() {
    console.log('DestroyerProxy destroy');
    this.props.destroy();
    super.destroy(true);
  }
}
