import { CardSuit, CardValue, IPlayCard, makeGrid } from "../../../common";
import { cssColorToInt } from "@kvisaz/phaser-sugar";

interface ICreateGridProps {
  scene: Phaser.Scene;
  playCards: IPlayCard[];
  locale: "en" | "ru";
  itemsPerRow?: number;
  cardBuilder: (
    suit: CardSuit,
    value: CardValue,
  ) => Phaser.GameObjects.GameObject & {
    getBounds(): Phaser.Geom.Rectangle;
    setPosition(x: number, y: number): unknown;
  };
}

export function createCardGrid({ scene, playCards, itemsPerRow = 4, cardBuilder }: ICreateGridProps) {
  const cardContainer = new Phaser.GameObjects.Container(scene);
  const cardViews = playCards.map((playCard) => cardBuilder(playCard.suit, playCard.value));
  const cardBounds = cardViews[0].getBounds();
  makeGrid({
    objects: cardViews,
    colStep: cardBounds.width * 1.05,
    rowStep: cardBounds.height * 1.05,
    unitInRow: itemsPerRow,
    centerLastRow: true,
  });
  cardContainer.add(cardViews);

  return cardContainer;
}

export function addCardZone({
  scene,
  width = 350,
  height = 350,
  cssColor,
}: {
  scene: Phaser.Scene;
  width?: number;
  height?: number;
  cssColor: string;
}) {
  const zone = new Phaser.GameObjects.Rectangle(
    scene,
    0,
    0,
    width,
    height,
    cssColorToInt(cssColor),
    0.75,
  ).setStrokeStyle(4, cssColorToInt(cssColor));
  scene.add.existing(zone);
  return zone;
}
