import { atlases } from "../atlases";

const atlas = atlases.background;
const TEXTURE_NAME = atlas.textureName;
type FrameName = keyof (typeof atlas)["frames"];

type SceneBgType = "game" | "start" | "adFull" | "levels";

/**
 * билдер для графических ассетов фонов
 * методы этого класса не должны меняться в стандартных играх
 * **/

export class BackgroundAssetBuilder {
  constructor(private scene: Phaser.Scene) {}

  sceneBg(type: SceneBgType = "game") {
    let frameName: FrameName = "bg.game.screen.1280x720.png";
    if (type === "start") {
      frameName = "bg.start.screen.1280x720.png";
    }

    const bg = image(this.scene, frameName).setOrigin(0, 0);
    this.scene.add.existing(bg);
    return bg;
  }
}

function nineSlice(
  scene: Phaser.Scene,
  frameName: FrameName,
  width: number,
  height: number,
  padding = 32,
): Phaser.GameObjects.NineSlice {
  return new Phaser.GameObjects.NineSlice(
    scene,
    0,
    0,
    TEXTURE_NAME,
    frameName,
    width,
    height,
    padding,
    padding,
    padding,
    padding,
  );
}

function image(scene: Phaser.Scene, frameName: FrameName): Phaser.GameObjects.Image {
  return new Phaser.GameObjects.Image(scene, 0, 0, TEXTURE_NAME, frameName);
}
