import type { ISO_639_1, SDK } from "ysdk";
import { delay } from "@kvisaz/phaser-sugar";
import { globalEvents } from "../../globalEvents";

interface IProps {
  onInitSuccess: (lang: ISO_639_1) => void;
}

/** Полная обертка и независимость для сцен
 *  от импортов и вообще наличия SDK
 *  под конкретную рекламу или API
 ***/
export class YandexGamesService {
  private ysdk: SDK | undefined;
  private state = {
    isGameStarted: false,
  };
  private unSubs: (() => void)[];

  constructor(private props: IProps) {
    /** реакция на boot - загрузка через сервисы **/
    this.unSubs = [
      globalEvents.on("startSceneStart", () => {
        this.onGameLoadFinish();
        this.onGamePlayStop();
      }),
      globalEvents.on("levelSceneStart", () => {
        this.onGamePlayStop();
      }),
      globalEvents.on("gameSceneStart", () => {
        this.onGamePlayStart();
      }),
      globalEvents.on("gameOverSceneStart", () => {
        this.onGamePlayStop();
      }),
    ];
  }

  clear() {
    this.unSubs.forEach((unSub) => unSub());
  }

  async init(timeOutMs = 5000) {
    await Promise.race([delay(timeOutMs), this.initYandex()]);
  }

  // Игровой процесс начался
  onGamePlayStart() {
    if (this.state.isGameStarted) return;
    this.state.isGameStarted = true;
    this.ysdk?.features.GameplayAPI.start();
  }

  // Игровой процесс закончился
  onGamePlayStop() {
    if (!this.state.isGameStarted) return;
    this.state.isGameStarted = false;
    this.ysdk?.features.GameplayAPI.stop();
  }

  onGameLoadFinish() {
    this.ysdk?.features.LoadingAPI?.ready();
  }

  showFullscreenAdv(onClose: (wasShown: boolean) => void, onError?: (error: string) => void) {
    const { ysdk } = this;
    if (ysdk == null) {
      onClose(false);
      return;
    }

    ysdk.adv.showFullscreenAdv({
      callbacks: {
        onClose: (wasShown) => {
          onClose(wasShown);
        },
        onError: (error) => {
          console.log("Ошибка при показе рекламы.");
          onError?.(error);
        },
      },
    });
  }

  private async initYandex() {
    if (YaGames == null) {
      console.warn("ru.yandex.games.sdk.YandexGames is not defined.");
      return;
    }
    try {
      // Сохраняем для использования в других сценах
      this.ysdk = await YaGames.init();
      const lang = this.ysdk.environment.i18n.lang;
      this.props.onInitSuccess(lang);
    } catch (e) {
      console.warn(e);
    }
  }
}
