import { UiAssetBuilder } from "../../assets";
import { gameObjectButton } from "../../components/ui";
import { services } from "../../serviceProvider";
import { SceneEvents, SoundEffect } from "../../SceneEvents";

interface IProps {
  scene: Phaser.Scene;
}

export function uiIconSoundButton({ scene }: IProps) {
  const builder = new UiAssetBuilder(scene);

  const { soundMusicSettings } = services;
  soundMusicSettings.load();
  const isSoundOn = soundMusicSettings.isSoundOn();

  const gameObject = builder.buttonIconSound();
  gameObject.setOn(isSoundOn);

  const onClick = () => {
    const isSoundOn = !soundMusicSettings.isSoundOn();
    sceneEvents.emit("soundSettingsOn", isSoundOn);
    gameObject.setOn(isSoundOn);
  };

  const sceneEvents = new SceneEvents(scene);

  return gameObjectButton({
    gameObject,
    inputTracker: gameObject,
    onClick: () => {
      sceneEvents.emit("soundEffect", SoundEffect.click);
      onClick();
    },
    onOver: () => {
      sceneEvents.emit("soundEffect", SoundEffect.buttonHover);
    },
    options: {
      once: false,
      overMoveY: 4,
      clickMode: "up",
    },
  }) as Phaser.GameObjects.Image;
}
