import { ASSETS, BackgroundAssetBuilder, CardAssetBuilder, getCurrentLocale } from "../../../assets";
import { services } from "../../../serviceProvider";
import { SoundManager } from "../../../ui";
import { addBackButton, addText } from "../utils";
import { Scenes } from "../../routes";
import { cardClassic52Deck, CardSuit, CardValue, isFigureCard, resetSearchParam } from "../../../common";
import { Align } from "@kvisaz/phaser-sugar";
import { createCardGrid } from "./cardUtils";

export class CardFiguresScene extends Phaser.Scene {
  preload() {}

  create() {
    const scene = this;
    const { soundMusicSettings } = services;
    const soundManager = new SoundManager({ scene, soundMusicSettings });
    new BackgroundAssetBuilder(scene).sceneBg();
    const align = new Align();

    const soundNames = Object.keys(ASSETS.sounds.effect);
    console.log(soundNames);

    /** backCover button **/
    addBackButton({
      scene: this,
      onClick: () => {
        resetSearchParam("test");
        scene.scene.start(Scenes.TestScene);
      },
    });

    /** Main test **/
    const title = addText(scene, "Figures test");
    align.anchorSceneScreen(scene).leftIn(title, 12).topIn(title, 80);
    this.add.existing(title);

    /** select data for cards **/
    const allCards = cardClassic52Deck.cards.all;
    const FIGURES = allCards.filter((card) => isFigureCard(card.value));
    console.log("FIGURES", FIGURES);

    /** card builder **/
    const cardAssetBuilder = new CardAssetBuilder({ scene, locale: getCurrentLocale() });
    const cardBuilder = (suit: CardSuit, value: CardValue) => {
      return cardAssetBuilder.cardFace(suit, value);
    };

    /** create card grid **/
    const cardContainer = createCardGrid({
      scene: this,
      playCards: FIGURES,
      locale: getCurrentLocale(),
      cardBuilder,
    }).setScale(0.7);
    this.add.existing(cardContainer);
    align.anchorSceneScreen(this).center(cardContainer).topIn(cardContainer, 30);
  }
}
