import { getCanvasSize } from "../../size";
import { cssColorToInt } from "@kvisaz/phaser-sugar";

interface IProps {
  scene: Phaser.Scene;
  width?: number;
  height?: number;
  cssColor?: string;
}

interface IBounded extends Phaser.GameObjects.GameObject {
  setPosition(x: number, y: number): this;

  x: number;
  y: number;

  destroy(fromScene?: boolean): void;
}

/** контейнер для лейаута - не решенная проблема
 * - при его setPosition соответственно сменяются позиции его детей
 * не тестировался на Tween
 **/
export class ViewPortContainer extends Phaser.GameObjects.Rectangle {
  private boundedObjects: IBounded[];

  get children() {
    return this.boundedObjects;
  }

  constructor(props: IProps) {
    const sceneBounds = getCanvasSize(props.scene);
    const { scene, cssColor, width = sceneBounds.width, height = sceneBounds.height } = props;
    super(scene, 0, 0, width, height);
    if (cssColor) {
      this.setFillStyle(cssColorToInt(cssColor));
    }
    this.boundedObjects = [];
  }

  destroy(fromScene?: boolean) {
    super.destroy(fromScene);
    this.boundedObjects.forEach((obj) => obj.destroy());
  }

  add(objects: IBounded[]) {
    objects.forEach((obj) => this.boundedObjects.push(obj));
  }

  override setPosition(x: number, y: number): this {
    const dX = x - this.x;
    const dY = y - this.y;
    super.setPosition(x, y);
    this.updateBoundedPositions(x, dX, y, dY);
    return this;
  }

  private updateBoundedPositions(x: number, dX: number, y: number, dY: number) {
    this.boundedObjects.forEach((obj) => {
      obj.setPosition(obj.x + dX, obj.y + dY);
    });
  }
}
