import { getCanvasSize } from "../common";
import { Align } from "@kvisaz/phaser-sugar";

/** Мощная утилита без привязки и булшита **/
export class InputBlocker {
  private static INPUT_BLOCKER_KEY_NAME = 'INPUT_BLOCKER_KEY_NAME';
  /** add input blocker to scene, returns clear functions **/
  static disableInput(scene: Phaser.Scene) {
    const { width, height } = getCanvasSize(scene);
    const inputBlocker = new Phaser.GameObjects.Rectangle(scene, 0, 0, width, height, 0x000000, 0);
    inputBlocker.setName(InputBlocker.INPUT_BLOCKER_KEY_NAME);
    Align.setLeftTop(inputBlocker, 0, 0);
    scene.add.existing(inputBlocker);
    inputBlocker.setInteractive();

    return () => {
      inputBlocker.destroy();
    };
  }

  /** try to find inputBlocker in current scene and destroy it **/
  static enableInput(scene: Phaser.Scene) {
    const inputBlocker = scene.children.getByName(InputBlocker.INPUT_BLOCKER_KEY_NAME);
    inputBlocker?.destroy();
  }
}
