import { Align } from "@kvisaz/phaser-sugar";
import { ASSETS } from "../../../assets";
import { makeGrid } from "../../../common";

interface IButtonData {
  textColor?: string;
  bgColor?: string;
  text: string;
  padding?: number;
  fontSize?: string;
  width?: number;
  height?: number;
  onClick: () => void;
}

interface IProps {
  scene: Phaser.Scene;
  title: string;
  buttonsData: IButtonData[];
}

export function addTestButtons({ scene, buttonsData, title }: IProps) {
  const align = new Align();

  /** title **/
  const titleView = new Phaser.GameObjects.Text(scene, 0, 0, title, {
    fontFamily: ASSETS.font.fonts.RobotoBold.fontFamily,
    color: "#c7d7e1",
    fontSize: "32px",
  });
  scene.add.existing(titleView);
  align.anchorSceneScreen(scene).center(titleView).topIn(titleView, 30);

  const buttons = buttonsData.map((data) => addTestButton({ scene, ...data }));

  const bounds = buttons[0].getBounds();

  makeGrid({
    objects: buttons,
    colStep: bounds.width * 1.2,
    rowStep: bounds.height * 1.4,
    unitInRow: 4,
    centerLastRow: true,
  });
  const buttonContainer = new Phaser.GameObjects.Container(scene, 0, 0, buttons);

  scene.add.existing(buttonContainer);

  align.anchorSceneScreen(scene).center(buttonContainer).topIn(buttonContainer, 200);
}

export function addTestButton({
  scene,
  onClick,
  text,
  bgColor,
  textColor,
  fontSize,
  width = 200,
  height = 0,
  padding = 20,
}: {
  scene: Phaser.Scene;
} & IButtonData) {
  const textButton = new Phaser.GameObjects.Text(scene, 0, 0, text, {
    fontFamily: ASSETS.font.fonts.RobotoBold.fontFamily,
    fontSize: fontSize ?? "24px",
    padding: {
      top: padding,
      right: padding,
      bottom: padding,
      left: padding,
    },
    align: "center",
    fixedWidth: width,
    fixedHeight: height,
    backgroundColor: bgColor ?? "#f1ce3d",
    color: textColor ?? "#070707",
  });

  textButton.on(Phaser.Input.Events.POINTER_DOWN, () => {
    console.log("click on button ", text);
    onClick();
  });
  textButton.setInteractive({
    useHandCursor: true,
  });

  return textButton;
}

export function addBackButton({ scene, onClick }: { scene: Phaser.Scene; onClick: () => void }) {
  const button = addTestButton({
    scene,
    text: "<< Back",
    onClick,
    bgColor: "#f1ce3d",
    textColor: "#070707",
    fontSize: "16px",
    width: 0,
    height: 0,
    padding: 10,
  });
  new Align().anchorSceneScreen(scene).leftIn(button, 10).topIn(button, 10);
  scene.add.existing(button);
  return button;
}
