import { DragObject, DropZone } from "./interfaces";
import { overlapAreaByBounds } from "./overlap/overlap";
import { DragDropChecker, findFirstDroppableOverlap, OverlapAreaConfig } from "../../gameObjects";
import { IBoundable } from "../../games/cards-abstract/abstract_types";

interface IProps {
  dragObjects: DragObject[];
  dropZones: DropZone[];

  onDragStart?: (dragObject: DragObject) => void;

  /** when some dragObject is overlap dropZone **/
  onDropZoneEnter?: (dragObject: DragObject, dropZone: DropZone) => void;
  onDropZoneLeave?: (dragObject: DragObject, dropZone: DropZone) => void;

  /** dragObject is dropped on dropZone **/
  onDrop: (dragObject: DragObject, dropZone: DropZone) => void;

  /** dragObject is not dropped and will be moved to start pos **/
  onDropReset: (dragObject: DragObject) => void;

  /** can some dragObject be dropped to dropZone **/
  isDroppable?: (dragObject: DragObject, dropZone: DropZone) => boolean;

  options?: Partial<IOptions>;
}

interface IOptions {
  restorePositionOnDropReset: boolean;
  restorePosition: (dragObject: DragObject, x: number, y: number) => void;
  isOverlapped: (dragObject: DragObject, dropZone: DropZone) => boolean;
  /** 'first' — первая подходящая зона; 'maxOverlap' — зона с наибольшей площадью пересечения */
  dropZoneSelection: "first" | "maxOverlap";
  getOverlapArea: (dragObject: DragObject, dropZone: DropZone) => number;
  minOverlapArea?: number;
}

const defaultOptions: IOptions = {
  restorePositionOnDropReset: true,
  restorePosition: (dragObject, x, y) => {
    dragObject.x = x;
    dragObject.y = y;
  },
  dropZoneSelection: "maxOverlap",
  isOverlapped: (dragObject, dropZone) => {
    return Phaser.Geom.Rectangle.Overlaps(dragObject.getBounds(), dropZone.getBounds());
  },
  getOverlapArea: overlapAreaByBounds,
  minOverlapArea: 0,
};

/**
 * create drag drop and return unsubscribes
 *  - auto unsubscribe when scene shutdown / destroyed
 *  - dropzones - any game object!
 * **/
export function addDragDropZen({
  dragObjects,
  dropZones,
  onDragStart,
  onDrop,
  onDropReset,
  onDropZoneEnter,
  onDropZoneLeave,
  isDroppable = () => true,
  options = {},
}: IProps) {
  const config: IOptions = { ...defaultOptions, ...options };
  const overLapConfig: OverlapAreaConfig = {
    isDroppable: isDroppable as DragDropChecker<IBoundable>,
  };

  const unSubs: (() => void)[] = [];
  const unSubscribe = () => {
    unSubs.forEach((f) => f());
    unSubs.length = 0;
  };

  if (dragObjects.length == 0) {
    console.warn("dragObjects.length==0");
    return unSubscribe;
  }

  if (dropZones.length == 0) {
    console.warn("dropZones.length==0");
    return unSubscribe;
  }

  const scene = dragObjects[0].scene as Phaser.Scene | undefined;
  if (scene == null) return unSubscribe;

  /** auto unsubscribe  **/
  scene.events.once(Phaser.Scenes.Events.SHUTDOWN, unSubscribe);
  scene.events.once(Phaser.Scenes.Events.DESTROY, unSubscribe);

  /** set interactive  **/
  dragObjects.forEach((dragObject) => {
    setInteractive(dragObject);
  });
  scene.input.setDraggable(dragObjects);
  unSubs.push(() => {
    dragObjects.forEach((dragObject) => {
      if (dragObject.scene == null) return;
      disableInteractive(dragObject);
      scene.input.setDraggable(dragObject, false);
    });
  });

  /** проверка объектов над зонами **/
  const overZoneByDrag = new Map<DragObject, DropZone | null>();
  unSubs.push(() => overZoneByDrag.clear());

  /** on drag start **/
  const onDragStartCallback = (pointer: Phaser.Input.Pointer, gameObject: DragObject) => {
    scene.children.bringToTop(gameObject);
    onDragStart?.(gameObject);
  };
  scene.input.on(Phaser.Input.Events.DRAG_START, onDragStartCallback);
  unSubs.push(() => scene.input.off(Phaser.Input.Events.DRAG_START, onDragStartCallback));

  /** on drag **/
  const onDragCallback = (pointer: Phaser.Input.Pointer, gameObject: DragObject, dragX: number, dragY: number) => {
    gameObject.x = dragX;
    gameObject.y = dragY;

    /** on drop zone over **/
    if (onDropZoneEnter || onDropZoneLeave) {
      const prev = overZoneByDrag.get(gameObject) ?? null;
      const curr = findFirstDroppableOverlap(gameObject, dropZones, overLapConfig);

      if (curr !== prev) {
        if (prev) onDropZoneLeave?.(gameObject, prev);
        if (curr) onDropZoneEnter?.(gameObject, curr);
        overZoneByDrag.set(gameObject, curr);
      }
    }
  };
  scene.input.on(Phaser.Input.Events.DRAG, onDragCallback);
  unSubs.push(() => scene.input.off(Phaser.Input.Events.DRAG, onDragCallback));

  /** on drag end **/
  const onDragEndCallback = (pointer: Phaser.Input.Pointer, gameObject: DragObject, dropped: boolean) => {
    const prevZone = overZoneByDrag.get(gameObject) ?? null;

    const onFinishResetDropZone = () => {
      overZoneByDrag.set(gameObject, null);
      if (prevZone && onDropZoneLeave) onDropZoneLeave(gameObject, prevZone);
    };

    const dz = findFirstDroppableOverlap(gameObject, dropZones, overLapConfig);
    if (dz) {
      onDrop(gameObject, dz);
      overZoneByDrag.set(gameObject, null);
      if (prevZone && onDropZoneLeave && prevZone !== dz) {
        onDropZoneLeave(gameObject, prevZone);
      }
    } else {
      /** else reset **/
      if (config.restorePositionOnDropReset) {
        const toX = gameObject.input?.dragStartX ?? gameObject.x;
        const toY = gameObject.input?.dragStartY ?? gameObject.y;
        config.restorePosition(gameObject, toX, toY);
      }
    }

    onDropReset(gameObject);
    onFinishResetDropZone();
  };

  scene.input.on(Phaser.Input.Events.DRAG_END, onDragEndCallback);
  unSubs.push(() => scene.input.off(Phaser.Input.Events.DRAG_END, onDragEndCallback));

  /** .......  **/

  return unSubscribe;
}

function setInteractive(dragObject: DragObject) {
  if (isContainer(dragObject)) {
    const { width, height } = dragObject.getBounds();
    dragObject.setSize(width, height);
  }

  if (dragObject.input == null) {
    dragObject.setInteractive({ useHandCursor: true });
  }
}

function disableInteractive(dragObject: DragObject) {
  dragObject.disableInteractive();
}

function isContainer(obj: Phaser.GameObjects.GameObject): obj is Phaser.GameObjects.Container {
  return obj.type === "Container";
}
