interface INineSliceArgs {
  scene: Phaser.Scene;
  width: number;
  height: number;
  texture: string;
  frame: string;
  left: number; // padding
  right: number; // padding
  top: number; // padding
  bottom: number; // padding
}

/**
 * Optimized, I hope, nine slice from Phaser creator
 * central area is stretched
 * if you want to repeat - try NinePatch
 **/
export class NineSlice extends Phaser.GameObjects.NineSlice {
  constructor(args: INineSliceArgs) {
    super(args.scene, 0, 0,
      args.texture, args.frame,
      args.width, args.height,
      args.left, args.right,
      args.top, args.bottom);
  }
}
