import { atlases } from "../atlases";

const atlas = atlases.ui;
const TEXTURE_NAME = atlas.textureName;
type FrameName = keyof (typeof atlas)["frames"];

/**
 * билдер графических ассетов UI
 *
 * Названия методов должны меняться крайне редко
 * в идеале никогда
 * просто подменяем ассеты тут - и во всех остальных зависимостях
 * получаем 0 изменений
 * **/
export class UiAssetBuilder {
  atlas = atlas;

  constructor(private scene: Phaser.Scene) {}

  dialogBg(w: number, h: number) {
    return nineSlice(this.scene, "nineslice.dialog.frame.dark.png", w, h);
  }

  dialogContentFrame(w: number, h: number) {
    return nineSlice(this.scene, "color.272731.rect.png", w, h);
  }

  buttonAccent(w = 169, h = 63) {
    return nineSlice(this.scene, "nineslice.button.green.accent.png", w, h);
  }

  buttonNeutral(w = 169, h = 63) {
    return nineSlice(this.scene, "nineslice.button.green.neutral.png", w, h);
  }

  buttonDanger(w = 169, h = 63) {
    return nineSlice(this.scene, "nineslice.button.green.danger.png", w, h);
  }

  buttonIconSound() {
    return new TwoStateButton({
      scene: this.scene,
      onFrame: "icon.volume.on.png",
      offFrame: "icon.volume.off.png",
    });
  }

  buttonIconMusic() {
    return new TwoStateButton({
      scene: this.scene,
      onFrame: "icon.music.on.png",
      offFrame: "icon.music.off.png",
    });
  }

  buttonSettings() {
    return image(this.scene, "button.icon.settings.png");
  }

  buttonIconBack() {
    return image(this.scene, "button.icon.back.png");
  }

  buttonIconRewind() {
    return image(this.scene, "button.icon.rewind.png");
  }
}

function nineSlice(
  scene: Phaser.Scene,
  frameName: FrameName,
  width: number,
  height: number,
  padding = 16,
): Phaser.GameObjects.NineSlice {
  return new Phaser.GameObjects.NineSlice(
    scene,
    0,
    0,
    TEXTURE_NAME,
    frameName,
    width,
    height,
    padding,
    padding,
    padding,
    padding,
  );
}

function image(scene: Phaser.Scene, frameName: FrameName): Phaser.GameObjects.Image {
  return new Phaser.GameObjects.Image(scene, 0, 0, TEXTURE_NAME, frameName);
}

export class TwoStateButton extends Phaser.GameObjects.Image {
  constructor(private props: { scene: Phaser.Scene; onFrame: FrameName; offFrame: FrameName }) {
    super(props.scene, 0, 0, TEXTURE_NAME, props.onFrame);
  }

  setOn(on: boolean) {
    this.setFrame(on ? this.props.onFrame : this.props.offFrame);
  }

  isOn() {
    return this.frame.name === this.props.onFrame;
  }
}

export class IconButtonMusic extends TwoStateButton {
  constructor(props: { scene: Phaser.Scene }) {
    super({
      scene: props.scene,
      onFrame: "icon.music.on.png",
      offFrame: "icon.music.off.png",
    });
  }
}
